from __future__ import unicode_literals

from ute_common_util.test.temp import path_to_resource
from ute_common_config_files.scfc.scfc import Scfc
from functools import partial
from unittest import TestCase

path_to_resource = partial(path_to_resource, __name__)

DIST_NAME = "MRBTS-1/BTSSCL-1/LCELL-1"


class TestManagedObjectWithPrefix(TestCase):
    @path_to_resource('resources/scfc/empty_managed_object_with_prefix.xml')
    def test_mo_with_prefix_and_find_with_prefix(self, scfc_path):
        lcells = Scfc(scfc_path).find_managed_objects('com.nokia.srbts.mnl:LCELL')
        self.assertEqual(len(lcells), 1)
        self.assertEqual(lcells[0].klass, 'com.nokia.srbts.mnl:LCELL')

    @path_to_resource('resources/scfc/empty_managed_object_with_prefix.xml')
    def test_mo_with_prefix_and_find_without_prefix(self, scfc_path):
        lcells = Scfc(scfc_path).find_managed_objects('LCELL')
        self.assertEqual(len(lcells), 1)
        self.assertEqual(lcells[0].klass, 'com.nokia.srbts.mnl:LCELL')

    @path_to_resource('resources/scfc/empty_managed_object.xml')
    def test_mo_without_prefix_and_find_with_prefix(self, scfc_path):
        lcells = Scfc(scfc_path).find_managed_objects('com.nokia.srbts.mnl:LCELL')
        self.assertEqual(len(lcells), 0)

    @path_to_resource('resources/scfc/empty_managed_object.xml')
    def test_mo_without_prefix_and_find_without_prefix(self, scfc_path):
        lcells = Scfc(scfc_path).find_managed_objects('LCELL')
        self.assertEqual(len(lcells), 1)
        self.assertEqual(lcells[0].klass, 'LCELL')

    @path_to_resource('resources/scfc/empty_managed_object.xml')
    def test_mo_with_added_prefix(self, scfc_path):
        managed_object = Scfc(scfc_path).add_managed_object('/MRBTS-1/TEST-1', class_prefix='test_prefix')
        self.assertEqual(managed_object.klass, 'test_prefix:TEST')
